fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Collect the j-th element from each row to form a column vector
    // Preconditions: 
    // - input has n rows, each with m columns
    // - j < m
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Construct output matrix with m rows and n columns
    // Each output row is the j-th column of input
    // Preconditions:
    // - input.len() == n (number of rows)
    // - input[i].len() == m for all 0 <= i < n

    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}